import {directoryLabel} from './community-directory.js?v=20261023030157187';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n;};
const button=(text,work,cls='m5-button')=>{const n=el('button',text,cls);n.type='button';n.onclick=work;return n;};
export function createM5Admin({request,t,getUser,getLanguage,onError,onUnauthorized}){
 let generation=0,days=30,section='categories',selected=null,writing=false,controller=new AbortController();
 const language=()=>getLanguage?.()||'zh-CN';
 function leave(){generation++;controller.abort();controller=new AbortController();}
 function field(label,node){const wrap=el('label',undefined,'m5-field');wrap.append(el('span',label),node);return wrap;}
 function input(type,value=''){const node=el('input');node.type=type;node.value=String(value);return node;}
 function fail(error){if(!onUnauthorized?.(error))onError(t('saveError'));}
 async function directory(host){const ticket=++generation,owner=getUser()?.id;host.replaceChildren(el('p',t('loading')));
  try{const data=await request('/api/admin/directory',{signal:controller.signal});if(ticket!==generation||getUser()?.id!==owner)return;host.replaceChildren();const tabs=el('div',undefined,'m4-inbox-tabs');for(const [id,key]of [['categories','m5Categories'],['tags','m5Tags']]){const tab=button(t(key),()=>{section=id;selected=null;draw();});tab.setAttribute('aria-pressed',String(section===id));tabs.append(tab);}host.append(tabs,el('p',t('m5DirectoryNote'),'m5-admin-note'));const grid=el('div',undefined,'m5-admin-directory');host.append(grid);
   function draw(){if(ticket!==generation)return;for(const tab of tabs.children)tab.setAttribute('aria-pressed',String(tab.textContent===t(section==='categories'?'m5Categories':'m5Tags')));grid.replaceChildren();const list=el('div',undefined,'m5-directory-items'),editor=el('div');grid.append(list,editor);list.append(button(t('m5New'),()=>{selected=null;edit(null);}));for(const row of data[section]||[]){const b=button(directoryLabel(row,language()),()=>{selected=row.id;edit(row);},'m5-directory-row');b.append(el('small',row.id+(row.active?'':' · '+t('m5Inactive'))));list.append(b);}edit((data[section]||[]).find(row=>row.id===selected)||null);
    function edit(row){editor.replaceChildren();const form=el('form',undefined,'m5-directory-editor'),id=input('text',row?.id||''),name=input('text',row?.name||''),color=input('color',row?.color||'#999999'),position=input('number',row?.position||0),active=input('checkbox');id.readOnly=!!row;id.maxLength=40;id.required=true;id.pattern='[a-z][a-z0-9-]{0,39}';name.maxLength=60;name.required=true;position.min='0';position.max='10000';position.step='1';active.checked=row?!!row.active:true;form.append(field(t('m5Id'),id),field(t('m5Name'),name));if(section==='categories')form.append(field(t('m5Color'),color));form.append(field(t('m5Position'),position));const check=el('label',undefined,'m5-check');check.append(active,el('span',t('m5Active')));form.append(check,el('p',t('m5Translations'),'m5-admin-note'));const languages=['zh-CN','zh-TW','ja','en','ko'],translations={},translationGrid=el('div',undefined,'m5-translation-grid');for(const code of languages){const n=input('text',row?.translations?.[code]||'');n.maxLength=60;translations[code]=n;translationGrid.append(field(code,n));}form.append(translationGrid);const status=el('p',undefined,'m5-admin-note'),save=el('button',t('m5Save'),'m5-button primary');save.type='submit';save.disabled=writing;form.append(save,status);editor.append(form);
     form.onsubmit=async event=>{event.preventDefault();if(writing||ticket!==generation||getUser()?.id!==owner)return;writing=true;for(const node of form.querySelectorAll('input,button'))node.disabled=true;const targetSection=section,payload={expectedUserId:owner,id:id.value.trim(),name:name.value.trim(),position:Number(position.value),active:active.checked,translations:Object.fromEntries(languages.filter(code=>translations[code].value.trim()).map(code=>[code,translations[code].value.trim()])),...(targetSection==='categories'?{color:color.value}:{})};
      try{await request('/api/admin/directory/'+targetSection,{method:'POST',body:JSON.stringify(payload)});if(ticket!==generation||getUser()?.id!==owner)return;selected=payload.id;writing=false;await directory(host);}catch(error){if(ticket===generation&&getUser()?.id===owner){status.textContent=t('saveError')+(error.code?' ('+error.code+')':'');fail(error);}}finally{writing=false;if(ticket===generation)for(const node of form.querySelectorAll('input,button'))node.disabled=false;}
     };
    }
   }draw();
  }catch(error){if(ticket===generation&&getUser()?.id===owner){host.replaceChildren(el('p',t('error')),button(t('retry'),()=>directory(host)));fail(error);}}
 }
 async function insights(host){const ticket=++generation,owner=getUser()?.id;host.replaceChildren(el('p',t('loading')));try{const data=await request('/api/admin/insights?days='+days,{signal:controller.signal});if(ticket!==generation||getUser()?.id!==owner)return;host.replaceChildren();const select=el('select',undefined,'m5-button');for(const value of [7,30,90]){const option=el('option',t('m5Days',{count:value}));option.value=String(value);select.append(option);}select.value=String(days);select.onchange=()=>{days=Number(select.value);insights(host);};host.append(select,el('p',t('m5Range')+': '+data.range.from+' → '+data.range.to,'m5-admin-note'));const grid=el('div',undefined,'m5-metric-grid');const labels={newMembers:'m5NewMembers',topics:'m5Topics',replies:'m5Replies',activeAuthors:'m5ActiveAuthors',solvedTopics:'m5SolvedTopics',reactions:'m5Reactions',openReports:'m5OpenReports'};for(const [key,label]of Object.entries(labels)){const card=el('article',undefined,'m5-metric');card.append(el('span',t(label)),el('strong',new Intl.NumberFormat(language()).format(data.metrics[key]||0)));grid.append(card);}host.append(grid,el('h2',t('m5Definitions')));const definitions=el('dl',undefined,'m5-definitions');const defined={newMembers:'m5DefineMembers',topics:'m5DefineTopics',replies:'m5DefineReplies',activeAuthors:'m5DefineAuthors',solvedTopics:'m5DefineSolved',reactions:'m5DefineReactions',openReports:'m5DefineReports'};for(const [key,label]of Object.entries(labels)){definitions.append(el('dt',t(label)),el('dd',t(defined[key])));}host.append(definitions);}catch(error){if(ticket===generation&&getUser()?.id===owner){host.replaceChildren(el('p',t('error')),button(t('retry'),()=>insights(host)));fail(error);}}}
 return {leave,directory,insights};
}
